def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def minCameraCover(tree):
    val, left, right = parse(tree)
    n = len(val)
    # 0 = not watched, 1 = watched, no camera, 2 = camera
    state = [0] * n
    cameras = 0
    for u in range(n - 1, -1, -1):
        kids = [state[c] for c in (left[u], right[u]) if c != -1]
        if 0 in kids:
            state[u] = 2
            cameras += 1
        elif 2 in kids:
            state[u] = 1
    if state[0] == 0:
        cameras += 1
    return cameras
